# DEEP10M distributed Auncel paths (4 shards, IVF1024, k=100).
# Source: source "${DIST}/sh/auncel_deep10m_env.sh"

AUNCEL_DEEP_DIR="${AUNCEL_DEEP_DIR:-/gpfs/scratch/delgaudio/vectors/DEEP}"
AUNCEL_LOG_DIR="${AUNCEL_LOG_DIR:-${AUNCEL_DEEP_DIR}/logs}"

# Raw inputs (.fbin / .bin — no fvecs conversion required for Auncel dist).
AUNCEL_BASE="${AUNCEL_BASE:-${AUNCEL_DEEP_DIR}/base.10M.fbin}"
AUNCEL_QUERY="${AUNCEL_QUERY:-${AUNCEL_DEEP_DIR}/query.public.10K.fbin}"
AUNCEL_GT="${AUNCEL_GT:-${AUNCEL_DEEP_DIR}/computedGT_deep10M_10kqueries_k100_faiss.bin}"

AUNCEL_SHARDS="${AUNCEL_SHARDS:-${AUNCEL_DEEP_DIR}/auncel_shards_4w}"
AUNCEL_INDEX_DIR="${AUNCEL_INDEX_DIR:-${AUNCEL_DEEP_DIR}/auncel_index_deep10m_4w}"

AUNCEL_NUM_SHARDS="${AUNCEL_NUM_SHARDS:-4}"
AUNCEL_K="${AUNCEL_K:-100}"
AUNCEL_INDEX_KEY="${AUNCEL_INDEX_KEY:-IVF1024,Flat}"
AUNCEL_VECTORS_PER_SHARD="${AUNCEL_VECTORS_PER_SHARD:-2500000}"

# Global id offsets for reduce (shard i -> i * 2.5M).
AUNCEL_SHARD_OFFSETS="${AUNCEL_SHARD_OFFSETS:-0 2500000 5000000 7500000}"

export AUNCEL_DEEP_DIR AUNCEL_LOG_DIR AUNCEL_BASE AUNCEL_QUERY AUNCEL_GT
export AUNCEL_SHARDS AUNCEL_INDEX_DIR AUNCEL_NUM_SHARDS AUNCEL_K
export AUNCEL_INDEX_KEY AUNCEL_VECTORS_PER_SHARD AUNCEL_SHARD_OFFSETS
